import pytest
from sqlalchemy import text

from app.db import engine


@pytest.mark.skipif(not engine.dialect.name.startswith("postgresql"), reason="PostgreSQL-specific")
def test_supabase_client_roles_cannot_access_public_tables():
    with engine.connect() as connection:
        # Exercise default privileges after the lockdown migration using objects created by postgres.
        connection.exec_driver_sql(
            "CREATE TABLE public.security_privilege_probe (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY)"
        )
        connection.exec_driver_sql("CREATE SEQUENCE public.security_privilege_probe_seq")
        roles = set(connection.execute(text(
            "SELECT rolname FROM pg_roles WHERE rolname IN ('anon', 'authenticated')"
        )).scalars())
        if not {"anon", "authenticated"}.issubset(roles):
            pytest.skip("Supabase client roles are not present")

        tables = connection.execute(text(
            "SELECT tablename FROM pg_tables WHERE schemaname = 'public'"
        )).scalars().all()
        for role in ("anon", "authenticated"):
            for table in tables:
                for privilege in ("SELECT", "INSERT", "UPDATE", "DELETE", "TRUNCATE", "REFERENCES", "TRIGGER"):
                    allowed = connection.execute(
                        text("SELECT has_table_privilege(:role, :table_name, :privilege)"),
                        {"role": role, "table_name": f"public.{table}", "privilege": privilege},
                    ).scalar_one()
                    assert not allowed, f"{role} unexpectedly has {privilege} on public.{table}"

        sequences = connection.execute(text(
            "SELECT sequencename FROM pg_sequences WHERE schemaname = 'public'"
        )).scalars().all()
        for role in ("anon", "authenticated"):
            for sequence in sequences:
                for privilege in ("USAGE", "SELECT", "UPDATE"):
                    allowed = connection.execute(
                        text("SELECT has_sequence_privilege(:role, :sequence_name, :privilege)"),
                        {"role": role, "sequence_name": f"public.{sequence}", "privilege": privilege},
                    ).scalar_one()
                    assert not allowed, f"{role} unexpectedly has {privilege} on public.{sequence}"
